css_variables:
:root {
  /* Primary */
  --color-primary-50: #F1FDFD;
  --color-primary-100: #E3FCFB;
  --color-primary-200: #BFF8F5;
  --color-primary-300: #8BF9F4;
  --color-primary-400: #51F6EE;
  --color-primary-500: #00FFF3;
  --color-primary-600: #00D6CC;
  --color-primary-700: #00B2AA;
  --color-primary-800: #038680;
  --color-primary-900: #036D68;
  --color-primary-950: #05423F;

  /* Secondary */
  --color-secondary-50: #FDF1F2;
  --color-secondary-100: #FCE3E5;
  --color-secondary-200: #F8BFC1;
  --color-secondary-300: #F98B90;
  --color-secondary-400: #F65158;
  --color-secondary-500: #FF000C;
  --color-secondary-600: #D6000A;
  --color-secondary-700: #B20008;
  --color-secondary-800: #86030A;
  --color-secondary-900: #6D0308;
  --color-secondary-950: #420508;

  /* Neutral */
  --color-neutral-50: #F7F8F8;
  --color-neutral-100: #F1F4F3;
  --color-neutral-200: #E3E8E8;
  --color-neutral-300: #CDD6D5;
  --color-neutral-400: #9AACAC;
  --color-neutral-500: #648785;
  --color-neutral-600: #4E6A68;
  --color-neutral-700: #3B4F4E;
  --color-neutral-800: #273534;
  --color-neutral-900: #182020;
  --color-neutral-950: #0D1211;

  /* Semantic */
  --color-success: #10B981;
  --color-success-light: #D1FAE5;
  --color-success-dark: #065F46;
  --color-success-50: #ECFDF5;
  --color-success-500: #10B981;
  --color-success-600: #059669;
  --color-success-700: #047857;
  --color-warning: #F59E0B;
  --color-warning-light: #FEF3C7;
  --color-warning-dark: #92400E;
  --color-warning-50: #FFFBEB;
  --color-warning-500: #F59E0B;
  --color-warning-600: #D97706;
  --color-warning-700: #B45309;
  --color-error: #EF4444;
  --color-error-light: #FEE2E2;
  --color-error-dark: #991B1B;
  --color-error-50: #FEF2F2;
  --color-error-500: #EF4444;
  --color-error-600: #DC2626;
  --color-error-700: #B91C1C;
  --color-info: #3B82F6;
  --color-info-light: #DBEAFE;
  --color-info-dark: #1E40AF;
  --color-info-50: #EFF6FF;
  --color-info-500: #3B82F6;
  --color-info-600: #2563EB;
  --color-info-700: #1D4ED8;

  /* Dark Mode (apply via [data-theme="dark"]) */
  --dark-background: #0B1413;
  --dark-surface: #182524;
  --dark-surface-elevated: #263635;
  --dark-text-primary: #F1F4F3;
  --dark-text-secondary: #B9C6C5;
  --dark-text-muted: #738C8B;
  --dark-border: #304140;
}
